{
  "claims": [
    {
      "claim_id": "c1",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that transaction IDs have a limited size of 32 bits.",
      "citations": [
        {
          "index": 0,
          "quote": "transaction IDs have limited size (32 bits)"
        }
      ]
    },
    {
      "claim_id": "c2",
      "reasoning": "The passage mentions that a cluster running for more than 4 billion transactions would suffer wraparound, implying the 32-bit space holds about 4 billion values.",
      "verdict": "SUPPORTED",
      "citations": [
        {
          "index": 0,
          "quote": "more than 4 billion transactions"
        }
      ]
    },
    {
      "claim_id": "c3",
      "reasoning": "The passage states that for every normal XID, there are two billion older and two billion newer XIDs.",
      "verdict": "SUPPORTED",
      "citations": [
        {
          "index": 1,
          "quote": "for every normal XID, there are two billion XIDs that are “older” and two billion that are “newer”"
        }
      ]
    },
    {
      "claim_id": "c4",
      "reasoning": "The passage explicitly states the necessity to vacuum every table at least once every two billion transactions to avoid wraparound.",
      "verdict": "SUPPORTED",
      "citations": [
        {
          "index": 0,
          "quote": "it is necessary to vacuum every table in every database at least once every two billion transactions."
        }
      ]
    },
    {
      "claim_id": "c5",
      "reasoning": "The passage clarifies that while it causes catastrophic data loss in the sense that data becomes invisible, the data is actually still there, contradicting the claim of permanent, unrecoverable data loss.",
      "verdict": "CONTRADICTED",
      "citations": [
        {
          "index": 0,
          "quote": "Actually the data is still there"
        }
      ]
    },
    {
      "claim_id": "c6",
      "reasoning": "The default autovacuum_freeze_max_age is 200 million, which is exactly 10% of the 2 billion transaction window mentioned for wraparound.",
      "verdict": "SUPPORTED",
      "citations": [
        {
          "index": 5,
          "quote": "The default, 200 million transactions"
        },
        {
          "index": 0,
          "quote": "at least once every two billion transactions"
        }
      ]
    },
    {
      "claim_id": "c7",
      "reasoning": "The effective maximum for vacuum_freeze_table_age is 0.95 * autovacuum_freeze_max_age. With the default of 200 million, the maximum is 190 million, not 180 million.",
      "verdict": "CONTRADICTED",
      "citations": [
        {
          "index": 4,
          "quote": "The effective maximum for vacuum_freeze_table_age is 0.95 * autovacuum_freeze_max_age"
        },
        {
          "index": 5,
          "quote": "The default, 200 million transactions"
        }
      ]
    },
    {
      "claim_id": "c8",
      "reasoning": "The warning is emitted at 40 million transactions from the wraparound point, and XID assignment stops at 3 million transactions left. The difference is 37 million.",
      "verdict": "SUPPORTED",
      "citations": [
        {
          "index": 6,
          "quote": "reach forty million transactions from the wraparound point"
        },
        {
          "index": 7,
          "quote": "refuse to assign new XIDs once there are fewer than three million transactions left until wraparound"
        }
      ]
    },
    {
      "claim_id": "c9",
      "reasoning": "The passage states that once XID assignment stops, only read-only transactions can be started, contradicting the claim that no new transactions of any kind can be started.",
      "verdict": "CONTRADICTED",
      "citations": [
        {
          "index": 8,
          "quote": "only read-only transactions can be started"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "claim_id": "c1",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that autovacuum cannot be used unless track_counts is set to true.",
      "citations": [
        {
          "index": 1,
          "quote": "autovacuum cannot be used unless track_counts is set to true."
        }
      ]
    },
    {
      "claim_id": "c2",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passage states that track_counts must be set to true for autovacuum to be used, but it does not state that this condition alone is sufficient for autovacuum to work.",
      "citations": []
    },
    {
      "claim_id": "c3",
      "verdict": "SUPPORTED",
      "reasoning": "The passage confirms that autovacuum is invoked on tables with unfrozen rows older than autovacuum_freeze_max_age, and explicitly notes that this happens even if autovacuum is disabled.",
      "citations": [
        {
          "index": 0,
          "quote": "autovacuum is invoked on any table that might contain unfrozen rows with XIDs older than the age specified by the configuration parameter autovacuum_freeze_max_age. (This will happen even if autovacuum is disabled.)"
        }
      ]
    },
    {
      "claim_id": "c4",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explains that a new worker is launched every autovacuum_naptime/N seconds, where N is the number of databases. With N=4 and autovacuum_naptime=60, a new worker starts every 60/4 = 15 seconds.",
      "citations": [
        {
          "index": 2,
          "quote": "Therefore, if the installation has N databases, a new worker will be launched every autovacuum_naptime/N seconds."
        }
      ]
    },
    {
      "claim_id": "c5",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage explicitly states that there is no limit on the number of workers that might be in a single database.",
      "citations": [
        {
          "index": 3,
          "quote": "There is no limit on how many workers might be in a single database"
        }
      ]
    },
    {
      "claim_id": "c6",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage states that the number of running autovacuum workers does not count towards the max_connections limit.",
      "citations": [
        {
          "index": 3,
          "quote": "Note that the number of running workers does not count towards max_connections or superuser_reserved_connections limits."
        }
      ]
    },
    {
      "claim_id": "c7",
      "verdict": "SUPPORTED",
      "reasoning": "The passage confirms that autovacuum processes table partitions just like other tables.",
      "citations": [
        {
          "index": 5,
          "quote": "Autovacuum does process table partitions just like other tables."
        }
      ]
    },
    {
      "claim_id": "c8",
      "verdict": "SUPPORTED",
      "reasoning": "The passages explicitly state that the autovacuum daemon does not run or issue ANALYZE commands for partitioned tables.",
      "citations": [
        {
          "index": 5,
          "quote": "autovacuum does not run ANALYZE on partitioned tables"
        },
        {
          "index": 8,
          "quote": "The autovacuum daemon does not issue ANALYZE commands for partitioned tables."
        }
      ]
    },
    {
      "claim_id": "c9",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that the autovacuum daemon does not issue ANALYZE commands for foreign tables.",
      "citations": [
        {
          "index": 7,
          "quote": "The autovacuum daemon does not issue ANALYZE commands for foreign tables"
        }
      ]
    },
    {
      "claim_id": "c10",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage states that if autovacuum is running to prevent transaction ID wraparound, it is not automatically interrupted by conflicting lock requests.",
      "citations": [
        {
          "index": 6,
          "quote": "However, if the autovacuum is running to prevent transaction ID wraparound (i.e., the autovacuum query name in the pg_stat_activity view ends with (to prevent wraparound)), the autovacuum is not automatically interrupted."
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "claim_id": "c1",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that the standard form of VACUUM can run in parallel with production database operations, including SELECT, INSERT, UPDATE, and DELETE.",
      "citations": [
        {
          "index": 0,
          "quote": "Also, the standard form of VACUUM can run in parallel with production database operations. (Commands such as SELECT, INSERT, UPDATE, and DELETE will continue to function normally"
        }
      ]
    },
    {
      "claim_id": "c2",
      "verdict": "SUPPORTED",
      "reasoning": "The passage directly states that VACUUM FULL requires an ACCESS EXCLUSIVE lock on the table.",
      "citations": [
        {
          "index": 0,
          "quote": "VACUUM FULL requires an ACCESS EXCLUSIVE lock on the table it is working on"
        }
      ]
    },
    {
      "claim_id": "c3",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage states that VACUUM FULL runs much more slowly than standard VACUUM, which contradicts the claim that it is faster.",
      "citations": [
        {
          "index": 0,
          "quote": "VACUUM FULL can reclaim more disk space but runs much more slowly."
        }
      ]
    },
    {
      "claim_id": "c4",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage notes an exception where standard VACUUM can return space to the operating system, contradicting the claim that it 'never' does so.",
      "citations": [
        {
          "index": 2,
          "quote": "However, it will not return the space to the operating system, except in the special case where one or more pages at the end of a table become entirely free and an exclusive table lock can be easily obtained."
        }
      ]
    },
    {
      "claim_id": "c5",
      "verdict": "SUPPORTED",
      "reasoning": "The passage confirms that VACUUM FULL, CLUSTER, and table-rewriting ALTER TABLE temporarily use extra disk space approximately equal to the size of the table.",
      "citations": [
        {
          "index": 6,
          "quote": "Note that they also temporarily use extra disk space approximately equal to the size of the table"
        }
      ]
    },
    {
      "claim_id": "c6",
      "verdict": "UNSUPPORTED",
      "reasoning": "While the passages state the general rule that extra disk space approximately equal to the table's size is needed, the specific figure of a 50 GB table is not mentioned or stated in the text.",
      "citations": []
    },
    {
      "claim_id": "c7",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that the autovacuum daemon will never issue VACUUM FULL, meaning any VACUUM FULL must have been started by something else.",
      "citations": [
        {
          "index": 3,
          "quote": "The autovacuum daemon attempts to work this way, and in fact will never issue VACUUM FULL."
        }
      ]
    },
    {
      "claim_id": "c8",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that TRUNCATE removes the entire content immediately without requiring a subsequent VACUUM to reclaim unused disk space.",
      "citations": [
        {
          "index": 7,
          "quote": "TRUNCATE removes the entire content of the table immediately, without requiring a subsequent VACUUM or VACUUM FULL to reclaim the now-unused disk space."
        }
      ]
    },
    {
      "claim_id": "c9",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly mentions that a disadvantage of TRUNCATE is that strict MVCC semantics are violated.",
      "citations": [
        {
          "index": 7,
          "quote": "The disadvantage is that strict MVCC semantics are violated."
        }
      ]
    },
    {
      "claim_id": "c10",
      "verdict": "SUPPORTED",
      "reasoning": "The passage confirms that some installations with extremely high update rates vacuum their busiest tables as often as once every few minutes.",
      "citations": [
        {
          "index": 5,
          "quote": "(Some installations with extremely high update rates vacuum their busiest tables as often as once every few minutes.)"
        }
      ]
    },
    {
      "claim_id": "c11",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage describes scheduling a database-wide VACUUM once a day as a 'typical approach' for those not using autovacuum, not as a strict requirement.",
      "citations": [
        {
          "index": 5,
          "quote": "For those not using autovacuum, a typical approach is to schedule a database-wide VACUUM once a day during a low-usage period"
        }
      ]
    }
  ]
}

