  "claims": [
    {
      "claim_id": "c1",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that in versions before 9.4, freezing replaced the insertion XID with FrozenTransactionId.",
      "citations": [
        {
          "index": 0,
          "quote": "In PostgreSQL versions before 9.4, freezing was implemented by actually replacing a row's insertion XID with FrozenTransactionId"
        }
      ]
    },
    {
      "claim_id": "c2",
      "verdict": "SUPPORTED",
      "reasoning": "The passage notes that before 9.4 (which includes 9.3), the replaced XID was visible in the xmin column, and FrozenTransactionId is equal to 2.",
      "citations": [
        {
          "index": 0,
          "quote": "In PostgreSQL versions before 9.4, freezing was implemented by actually replacing a row's insertion XID with FrozenTransactionId, which was visible in the row's xmin system column."
        },
        {
          "index": 0,
          "quote": "FrozenTransactionId (2)"
        }
      ]
    },
